import { doc, updateDoc } from "firebase/firestore"; // Firebase методи
import { db } from "../../config/firebaseConfig"; // Импортиране на конфигурацията за Firebase

export async function updateProject(title, subtitle, description, gitLink, img, projectId) {
    try {
        // Вземаме референция към документа на проекта в Firestore
        const projectRef = doc(db, "projects", projectId);

        // Актуализираме данните на проекта в Firestore
        await updateDoc(projectRef, {
            title,
            subtitle,
            description,
            gitLink,
            img
        });

        return { status: 200, message: 'Project updated successfully!' }; // Връщаме успешен отговор
    } catch (error) {
        console.error("Error updating project:", error);
        return { status: 500, message: 'Failed to update project. Please try again.' }; // Връщаме грешка при неуспешна актуализация
    }
}
